import{CITY_DATA,MODES,WEAPONS,createGame,updateForecast,riskForCity,applyCityAction,useWeapon,advanceTurn,nearestCity,bearingName,gradeGame,stormClass,projectLngLat,haversineKm}from'./engine.js';

let selectedMode='standard',game=null,turnAnimating=false;const $=s=>document.querySelector(s),$$=s=>[...document.querySelectorAll(s)];const NS='http://www.w3.org/2000/svg';
const clamp=(n,a,b)=>Math.max(a,Math.min(b,n));const mapPoint=p=>({x:(p.x??projectLngLat(p.lng,p.lat).x)*10,y:(p.y??projectLngLat(p.lng,p.lat).y)*6.8});
function showScreen(id){$$('.screen').forEach(x=>x.classList.remove('active'));$(id).classList.add('active')}
function save(){try{if(game)localStorage.setItem('stc-save-v2',JSON.stringify(game))}catch{}}
function normalizeSave(raw){if(!raw)return null;if(raw.version===2&&raw.storm?.lat&&raw.storm?.lng)return raw;const g=createGame(raw.seed||Date.now(),raw.modeKey||'standard');for(const k of ['turn','hour','day','month','year','ap','maxAp','intel','resources','selectedCity','totalDeaths','totalDamage'])if(raw[k]!==undefined)g[k]=raw[k];if(raw.storm?.lat&&raw.storm?.lng){Object.assign(g.storm,raw.storm,projectLngLat(raw.storm.lng,raw.storm.lat));g.storm.history=(raw.storm.history||[]).map(p=>p.lat?{...p,...projectLngLat(p.lng,p.lat)}:g.storm.history[0])}if(raw.cities)g.cities=g.cities.map(c=>({...c,...(raw.cities.find(x=>x.id===c.id)||{})}));return g}
function load(){try{return normalizeSave(JSON.parse(localStorage.getItem('stc-save-v2')||localStorage.getItem('stc-save')))}catch{return null}}
function toast(msg){const el=$('#eventToast');el.textContent=msg;el.classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>el.classList.remove('show'),2600)}
function svgEl(tag,attrs={}){const el=document.createElementNS(NS,tag);for(const[k,v]of Object.entries(attrs))el.setAttribute(k,v);return el}
function smoothPath(points){if(!points.length)return'';if(points.length===1)return`M${points[0].x} ${points[0].y}`;let d=`M${points[0].x} ${points[0].y}`;for(let i=0;i<points.length-1;i++){const p0=points[i-1]||points[i],p1=points[i],p2=points[i+1],p3=points[i+2]||p2;const c1={x:p1.x+(p2.x-p0.x)/6,y:p1.y+(p2.y-p0.y)/6},c2={x:p2.x-(p3.x-p1.x)/6,y:p2.y-(p3.y-p1.y)/6};d+=` C${c1.x.toFixed(1)} ${c1.y.toFixed(1)} ${c2.x.toFixed(1)} ${c2.y.toFixed(1)} ${p2.x.toFixed(1)} ${p2.y.toFixed(1)}`}return d}
function initGrid(){const g=$('#latLonGrid');g.innerHTML='';for(let lon=105;lon<=160;lon+=5){const p=projectLngLat(lon,0);g.appendChild(svgEl('line',{x1:p.x*10,y1:0,x2:p.x*10,y2:680}))}for(let lat=5;lat<=45;lat+=5){const p=projectLngLat(100,lat);g.appendChild(svgEl('line',{x1:0,y1:p.y*6.8,x2:1000,y2:p.y*6.8}))}}
function renderCities(){const layer=$('#cityLayer');layer.innerHTML='';game.cities.forEach(c=>{const risk=riskForCity(game,c),b=document.createElement('button');b.className=`city-marker priority-${c.priority||2} ${risk>72?'risk-high':''} ${c.status==='evacuating'?'evacuating':''} ${game.selectedCity===c.id?'selected':''}`;b.style.left=c.x+'%';b.style.top=c.y+'%';b.setAttribute('aria-label',`${c.name}，預測風險 ${risk}%`);b.innerHTML=`<span><b>${c.name}</b><small>${c.pop.toLocaleString()}萬人 · 風險${risk}%</small><small>撤離${Math.round(c.evac)}% · 防衛${Math.round(c.defense)}%</small></span>`;b.onclick=()=>{game.selectedCity=c.id;renderAll();save()};layer.appendChild(b)})}
function renderResources(){const labels=[['people','♟','人員'],['supplies','▣','物資'],['fuel','▤','燃料'],['power','ϟ','電力'],['medical','✚','醫療包'],['energy','◈','武器能源']];$('#resourceGrid').innerHTML=labels.map(([k,i,l])=>`<div class="resource-item"><span>${i}</span><small>${l}</small><b>${k==='power'||k==='energy'?Math.round(game.resources[k])+'%':Math.round(game.resources[k]).toLocaleString()}</b></div>`).join('')}
function renderWeapons(){const list=$('#weaponList');list.innerHTML='';game.weapons.forEach(w=>{const b=document.createElement('button');b.className=`weapon-card ${w.remaining?'cooldown':''}`;b.dataset.tone=w.tone;b.disabled=w.remaining>0||game.resources.energy<w.energy||game.ap<=0;b.innerHTML=`<div class="weapon-art">${w.glyph}</div><b>${w.name}</b><small>能源 ${w.energy}% · 成功率 ${Math.round((w.success+(game.intel-.5)*.18)*100)}%</small><small>${w.desc}</small><span class="weapon-status">${w.remaining?`冷卻 ${w.remaining} 回合`:'部署就緒'}</span>`;b.onclick=()=>{const r=useWeapon(game,w.id);toast(r.msg);updateForecast(game);renderAll();save()};list.appendChild(b)})}
function renderImpact(){const points=game.storm.forecast;$('#impactTimeline').innerHTML=points.map((p,i)=>{const near=nearestCity(game,p.lat,p.lng),hot=near.dist<p.spreadKm*.6;return`<div class="impact-step ${hot?'hot':''}"><span>${p.time.split(' ')[0]}</span><b>${stormClass(p.wind).level>=5?'⛈':stormClass(p.wind).level>=3?'🌀':'🌧'}</b><small>${near.city.name}</small></div>`}).join('');$('#lossBars').innerHTML=points.map(p=>{const near=nearestCity(game,p.lat,p.lng);const h=clamp(100-near.dist*.14+(p.wind-80)*.25,8,100);return`<i style="height:${h}%"></i>`}).join('')}
function buildCone(points){if(points.length<2)return'';const start=mapPoint(game.storm),left=[start],right=[start];points.forEach((p,i)=>{const cur=mapPoint(p),prev=mapPoint(i?points[i-1]:game.storm),next=mapPoint(points[i+1]||p);let dx=next.x-prev.x,dy=next.y-prev.y,len=Math.hypot(dx,dy)||1;dx/=len;dy/=len;const nx=-dy,ny=dx,rad=p.spreadKm*.135;left.push({x:cur.x+nx*rad,y:cur.y+ny*rad*.86});right.push({x:cur.x-nx*rad,y:cur.y-ny*rad*.86})});return`M${start.x} ${start.y} `+left.slice(1).map(p=>`L${p.x.toFixed(1)} ${p.y.toFixed(1)}`).join(' ')+right.reverse().slice(0,-1).map(p=>` L${p.x.toFixed(1)} ${p.y.toFixed(1)}`).join(' ')+' Z'}
function renderTrack(tempStorm=null){const s=tempStorm||game.storm,f=game.storm.forecast,start=mapPoint(s),forecastPts=[start,...f.map(mapPoint)];$('#forecastPath').setAttribute('d',smoothPath(forecastPts));$('#forecastCone').setAttribute('d',buildCone(f));
  const eGroup=$('#ensemblePaths');eGroup.innerHTML='';(game.storm.ensemble||[]).forEach(branch=>{const p=svgEl('path',{d:smoothPath([start,...branch.map(mapPoint)])});eGroup.appendChild(p)});
  const circles=$('#forecastCircles'),points=$('#forecastPoints');circles.innerHTML='';points.innerHTML='';f.forEach((p,i)=>{const q=mapPoint(p),r=p.spreadKm*.135;circles.appendChild(svgEl('ellipse',{cx:q.x,cy:q.y,rx:r,ry:r*.76}));const cls=stormClass(p.wind),g=svgEl('g');const c=svgEl('circle',{class:'track-dot',cx:q.x,cy:q.y,r:8,fill:cls.color});g.appendChild(c);const sym=svgEl('text',{x:q.x,y:q.y+3.2,'text-anchor':'middle','font-size':'9'});sym.textContent='◉';g.appendChild(sym);const box=svgEl('rect',{class:'time-box',x:q.x+10,y:q.y-16,width:65,height:15,rx:2});g.appendChild(box);const t=svgEl('text',{x:q.x+14,y:q.y-5});t.textContent=p.time;g.appendChild(t);points.appendChild(g)});
  const hist=(game.storm.history||[]).slice();if(tempStorm&&hist.length>1)hist[hist.length-1]=tempStorm;const hp=hist.map(mapPoint);$('#actualPath').setAttribute('d',smoothPath(hp));const actual=$('#actualPoints');actual.innerHTML='';hist.forEach((p,i)=>{const q=mapPoint(p),cls=stormClass(p.wind||game.storm.wind);actual.appendChild(svgEl('circle',{cx:q.x,cy:q.y,r:i===hist.length-1?5:3,fill:cls.color}));if(i===0||i===hist.length-1){const t=svgEl('text',{x:q.x+7,y:q.y-7});t.textContent=i===0?'生成':`T${Math.max(1,game.turn-1)}`;actual.appendChild(t)}})}
function renderWindRadii(s){const q=mapPoint(s),scale=.138;const r7=clamp(s.radius*1.75*scale,18,125),r10=clamp(s.radius*.92*scale,12,80);for(const[id,r]of[['#windRadius7',r7],['#windRadius10',r10]]){const c=$(id);c.setAttribute('cx',q.x);c.setAttribute('cy',q.y);c.setAttribute('r',r)}}
function estimateLandfall(){let best={dist:Infinity,city:game.cities[0],point:game.storm.forecast[0],index:0};game.storm.forecast.forEach((p,i)=>game.cities.forEach(c=>{const d=haversineKm(p.lat,p.lng,c.lat,c.lng);if(d<best.dist)best={dist:d,city:c,point:p,index:i}}));return best}
function updateStormData(s){const cls=stormClass(s.wind);$('#stormLevelBadge').textContent=`等級 ${cls.level} ${cls.label}`;$('#stormLevelBadge').style.color=cls.color;$('#stormName').textContent=s.name;$('#stormCode').textContent=s.code;$('#windValue').textContent=Math.round(s.wind);$('#pressureValue').textContent=Math.round(s.pressure);$('#moveSpeedValue').textContent=Math.round(s.speed);$('#directionValue').textContent=bearingName(Math.cos(s.heading),Math.sin(s.heading));$('#radiusValue').textContent=Math.round(s.radius);$('#seaTempValue').textContent=s.seaTemp.toFixed(1)+'°C';const near=nearestCity(game,s.lat,s.lng),land=estimateLandfall();$('#riskValue').textContent=land.dist<80?'極高':land.dist<180?'高':'中等';$('#landfallTime').textContent=`${land.point.time} · ${land.city.name}`;$('#livePosition').innerHTML=`<b>颱風實時位置 · SAT FIX</b><br>北緯 ${s.lat.toFixed(2)}°　東經 ${s.lng.toFixed(2)}°<br>最近城市：${near.city.name}（約 ${Math.round(near.dist)} km）<br>雲系直徑：約 ${Math.round(s.radius*4.4)} km<br>情報可信度：${Math.round(game.intel*100)}%`}
function renderStormVisual(s,updateTrack=true){const p=projectLngLat(s.lng,s.lat),el=$('#storm'),size=clamp(76+s.radius*1.18,155,535),cls=stormClass(s.wind);el.style.left=p.x+'%';el.style.top=p.y+'%';el.style.width=size+'px';el.style.height=size+'px';el.classList.toggle('severe',cls.level>=5);el.classList.toggle('catastrophic',cls.level>=6);const core=el.querySelector('.storm-core'),cloud=el.querySelector('.storm-cloud'),rain=el.querySelector('.storm-rainbands');core.style.animationDuration=clamp(22-s.wind*.055,6,16)+'s';cloud.style.animationDuration=clamp(32-s.wind*.07,10,24)+'s';rain.style.animationDuration=clamp(46-s.wind*.08,17,34)+'s';el.querySelectorAll('.lightning').forEach((l,i)=>l.style.animationDuration=clamp(8-s.wind*.018+i*.4,2.8,6.5)+'s');renderWindRadii({...s,...p});updateStormData({...s,...p});if(updateTrack)renderTrack({...s,...p})}
function renderAll(){if(!game)return;$('#gameDate').textContent=`${game.year} / ${game.month} / ${game.day}`;$('#gameTime').textContent=String(game.hour).padStart(2,'0')+':00';$('#turnLabel').textContent=game.turn;const gen=game.storm.genesis||game.storm;$('#genesisTime').textContent=gen.date||`${game.year}/${game.month}/${game.day} 03:00`;$('#genesisPos').textContent=`北緯 ${gen.lat.toFixed(2)}° 東經 ${gen.lng.toFixed(2)}°`;$('#apValue').textContent=game.ap;$('#apMax').textContent=game.maxAp;$('#intelSummary').textContent=Math.round(game.intel*100)+'%';const city=game.cities.find(c=>c.id===game.selectedCity)||game.cities[0];const cityRisk=riskForCity(game,city);$('#selectedCityName').textContent=city.name;$('#selectedCityCoords').textContent=`${city.lat.toFixed(2)}°N ${city.lng.toFixed(2)}°E`;$('#evacSummary').textContent=Math.round(city.evac)+'%';$('#defenseSummary').textContent=Math.round(city.defense)+'%';$('#supplySummary').textContent=Math.round(city.supplies)+'%';$('#cityPanelName').textContent=city.name;$('#cityPanelCoords').textContent=`${city.lat.toFixed(2)}°N · ${city.lng.toFixed(2)}°E`;$('#cityPanelRisk').textContent=`風險 ${cityRisk}%`;$('#cityPanelPopulation').textContent=`${city.pop.toLocaleString()} 萬`;$('#cityPanelCoastal').textContent=`${city.coastal.toLocaleString()} 萬`;$('#cityPanelEvac').textContent=`${Math.round(city.evac)}%`;$('#cityPanelDefense').textContent=`${Math.round(city.defense)}%`;$('#cityPanelSupply').textContent=`${Math.round(city.supplies)}%`;$('#cityPanelPower').textContent=`${Math.round(city.power)}%`;$('#cityPanelMedical').textContent=`${Math.round(city.medical)}%`;$('#cityPanelStatus').textContent=city.status==='normal'?'正常':city.status==='evacuating'?'撤離中':city.status==='damaged'?'受損':city.status==='critical'?'危急':'監測中';$('#endTurnButton').disabled=turnAnimating;renderCities();renderResources();renderWeapons();renderImpact();renderStormVisual(game.storm);$$('.phase').forEach((p,i)=>p.classList.toggle('active',i===Math.min(4,game.phase)))}
function start(seed,mode){game=createGame(seed,mode);updateForecast(game);showScreen('#gameScreen');renderAll();save()}
function lerp(a,b,t){return a+(b-a)*t}function angleLerp(a,b,t){let d=((b-a+Math.PI)%(Math.PI*2))-Math.PI;return a+d*t}
function animateStorm(before,after,duration=4500){return new Promise(resolve=>{const start=performance.now();function frame(now){const t=clamp((now-start)/duration,0,1),ease=t<.5?2*t*t:1-Math.pow(-2*t+2,2)/2;const current={...after,lat:lerp(before.lat,after.lat,ease),lng:lerp(before.lng,after.lng,ease),wind:lerp(before.wind,after.wind,ease),pressure:lerp(before.pressure,after.pressure,ease),radius:lerp(before.radius,after.radius,ease),seaTemp:lerp(before.seaTemp,after.seaTemp,ease),heading:angleLerp(before.heading,after.heading,ease)};renderStormVisual(current,true);if(t<1)requestAnimationFrame(frame);else resolve()}requestAnimationFrame(frame)})}
async function endTurn(){if(turnAnimating)return;turnAnimating=true;game.phase=3;renderAll();$('#storm').classList.add('is-moving');toast('部署鎖定，颱風開始自行移動…');const before=structuredClone(game.storm),result=advanceTurn(game),after=structuredClone(game.storm);await animateStorm(before,after,4600);$('#storm').classList.remove('is-moving');turnAnimating=false;if(result.event)toast(result.event);if(game.gameOver){save();setTimeout(showResults,700)}else{game.phase=2;renderAll();save()}}
function showResults(){const r=gradeGame(game);$('#grade').textContent=r.grade;$('#resultTitle').textContent=r.title;$('#resultSummary').textContent=`風暴行動於第 ${game.turn-1} 回合結束。你在有限情報下完成了城市部署，最終總傷亡為 ${game.totalDeaths.toLocaleString()} 人。`;$('#resultMetrics').innerHTML=`<div><span>最終分數</span><b>${r.score}</b></div><div><span>平均撤離率</span><b>${r.avgEvac}%</b></div><div><span>平均防衛度</span><b>${r.avgDefense}%</b></div><div><span>基建損失</span><b>${game.totalDamage}</b></div>`;showScreen('#resultScreen')}

initGrid();
$$('.mode-card').forEach(b=>b.onclick=()=>{$$('.mode-card').forEach(x=>x.classList.remove('selected'));b.classList.add('selected');selectedMode=b.dataset.mode});
$('#startButton').onclick=()=>start($('#seedInput').value||Date.now(),selectedMode);
$('#continueButton').onclick=()=>{const s=load();if(!s){alert('暫時沒有可讀取的存檔');return}game=s;updateForecast(game);showScreen('#gameScreen');renderAll()};
$$('[data-action]').forEach(b=>b.onclick=()=>{const r=applyCityAction(game,b.dataset.action);toast(r.msg);updateForecast(game);renderAll();save()});
$('#endTurnButton').onclick=endTurn;$('#retryButton').onclick=()=>start(game.seed,game.modeKey);$('#menuButton').onclick=()=>showScreen('#homeScreen');
$$('.map-toolbar button').forEach((b,i)=>b.onclick=()=>{b.classList.toggle('active');const stage=$('#mapStage');if(i===0)stage.classList.toggle('satellite-off',!b.classList.contains('active'));if(i===1)stage.classList.toggle('track-off',!b.classList.contains('active'));if(i===2)stage.classList.toggle('cities-off',!b.classList.contains('active'));if(i===3)stage.classList.toggle('wind-on',b.classList.contains('active'))});
window.addEventListener('resize',()=>{if(game&&$('#gameScreen').classList.contains('active'))renderStormVisual(game.storm)});
const demoParams=new URLSearchParams(location.search);if(demoParams.get('demo')==='1')start(demoParams.get('seed')||'20870716',demoParams.get('mode')||'standard');
